<script setup lang="ts">import{ref,onMounted,onUnmounted,computed}from'vue';import Tooltip from'./Tooltip.vue'
interface Td{id:string;label:string;swatches:string[]}
const BUILTIN:Td[]=[{id:'amber',label:'Amber',swatches:['#FFD700','#FFBF00','#CC9B1F']},{id:'blue',label:'Blue',swatches:['#44AAFF','#4499FF','#5588BB']},{id:'rose',label:'Rose',swatches:['#FF6699','#FF5599','#CC6699']},{id:'emerald',label:'Emerald',swatches:['#00E676','#00C853','#00897B']},{id:'purple',label:'Purple',swatches:['#CE93D8','#BA68C8','#8E24AA']}]
const CUSTOM_KEY='pebble-custom-themes'
const p=defineProps<{current:string;onChange:(id:string,hex?:string)=>void}>()
const o=ref(false);const sp=ref(false);const rr=ref<HTMLDivElement|null>(null);const ct=ref<Td[]>([])
const r=ref(255);const g=ref(215);const b=ref(0)
const hv=computed(()=>{const th=(v:number)=>Math.max(0,Math.min(255,v)).toString(16).padStart(2,'0');return`#${th(r.value)}${th(g.value)}${th(b.value)}`.toUpperCase()})
function hslf(rr:number,gg:number,bb:number):[number,number,number]{const rf=rr/255,gf=gg/255,bf=bb/255;const mx=Math.max(rf,gf,bf),mn=Math.min(rf,gf,bf);let h=0,s=0;const l=(mx+mn)/2;if(mx!==mn){const d=mx-mn;s=l>.5?d/(2-mx-mn):d/(mx+mn);if(mx===rf)h=((gf-bf)/d+(gf<bf?6:0))*60;else if(mx===gf)h=((bf-rf)/d+2)*60;else h=((rf-gf)/d+4)*60}return[Math.round(h),Math.round(s*100),Math.round(l*100)]}
function hth(h:number,s:number,l:number):string{const sf=s/100,lf=l/100;const c=(1-Math.abs(2*lf-1))*sf;const x=c*(1-Math.abs((h/60)%2-1));const m=lf-c/2;let rf=0,gf=0,bf=0;if(h<60){rf=c;gf=x}else if(h<120){rf=x;gf=c}else if(h<180){gf=c;bf=x}else if(h<240){gf=x;bf=c}else if(h<300){rf=x;bf=c}else{rf=c;bf=x}const th=(v:number)=>Math.round((v+m)*255).toString(16).padStart(2,'0');return`#${th(rf)}${th(gf)}${th(bf)}`.toUpperCase()}
function dc(hex:string):{primary:string;accent:string;muted:string;borderGold:string;glowStart:string;glowEnd:string}{const rr=parseInt(hex.slice(1,3),16),gg=parseInt(hex.slice(3,5),16),bb=parseInt(hex.slice(5,7),16);const[h,s,l]=hslf(rr,gg,bb);const a=hth(h,s,Math.max(0,l-12));const m2=hth(h,Math.max(0,s-25),Math.max(0,l-8));const bg=hth(h,Math.max(0,s-15),Math.max(0,l-30));return{primary:hex,accent:a,muted:m2,borderGold:bg,glowStart:`rgba(${rr},${gg},${bb},0.10)`,glowEnd:`rgba(${parseInt(bg.slice(1,3),16)},${parseInt(bg.slice(3,5),16)},${parseInt(bg.slice(5,7),16)},0.04)`}}
function ldct(){try{const raw=localStorage.getItem(CUSTOM_KEY);if(raw)ct.value=JSON.parse(raw)}catch{}}
function svct(){const hex=hv.value;const d=dc(hex);const sw=[d.primary,d.accent,d.muted];const lb=`Custom ${hex}`;const id=`custom-${Date.now()}`;const t:Td={id,label:lb,swatches:sw};ct.value.push(t);localStorage.setItem(CUSTOM_KEY,JSON.stringify(ct.value));localStorage.setItem(`pebble-theme-colors-${id}`,JSON.stringify(d));sp.value=false;p.onChange(id,hex);o.value=false}
function dlct(id:string){ct.value=ct.value.filter(t=>t.id!==id);localStorage.setItem(CUSTOM_KEY,JSON.stringify(ct.value));localStorage.removeItem(`pebble-theme-colors-${id}`);if(p.current===id)p.onChange('amber')}
function opnpk(){if(p.current.startsWith('custom-')){const s=localStorage.getItem(`pebble-theme-colors-${p.current}`);if(s){try{const c=JSON.parse(s);const h=c.primary;r.value=parseInt(h.slice(1,3),16);g.value=parseInt(h.slice(3,5),16);b.value=parseInt(h.slice(5,7),16)}catch{}}}sp.value=true}
function ap(){const hex=hv.value;const d=dc(hex);const rt=document.getElementById('app');if(!rt)return;rt.style.setProperty('--primary',d.primary);rt.style.setProperty('--accent',d.accent);rt.style.setProperty('--muted',d.muted);rt.style.setProperty('--border-gold',d.borderGold);rt.style.setProperty('--glow-start',d.glowStart);rt.style.setProperty('--glow-end',d.glowEnd)}
function clp(){const rt=document.getElementById('app');if(!rt)return;['--primary','--accent','--muted','--border-gold','--glow-start','--glow-end'].forEach(v=>rt.style.removeProperty(v))}
function hco(e:MouseEvent){if(rr.value&&!rr.value.contains(e.target as Node)){const wp=sp.value;o.value=false;sp.value=false;if(wp)clp()}}
function st(id:string){p.onChange(id);o.value=false;sp.value=false;clp()}
onMounted(()=>{ldct();document.addEventListener('mousedown',hco)});onUnmounted(()=>document.removeEventListener('mousedown',hco))
function hsc(){ap()};function hni(){ap()};function ccpk(){sp.value=false;clp()}
</script>
<template><div ref="rr" class="theme-swt"><Tooltip text="Theme" position="bottom"><button class="mc-btn theme-btn" @click="o=!o" aria-label="Switch theme"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="5"/><path d="M12 1v2M12 21v2M4.22 4.22l1.42 1.42M18.36 18.36l1.42 1.42M1 12h2M21 12h2M4.22 19.78l1.42-1.42M18.36 5.64l1.42-1.42"/></svg></button></Tooltip>
<div v-if="o" class="theme-dropdown"><div v-for="t in BUILTIN" :key="t.id" class="theme-opt" :class="{active:t.id===current}" @click="st(t.id)"><div class="theme-swatch-row"><span v-for="(c,i) in t.swatches" :key="i" class="theme-swatch" :style="{background:c}"/></div><span class="theme-opt-label">{{t.label}}</span><svg v-if="t.id===current" class="theme-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg></div>
<div class="theme-sep"/>
<div v-for="t in ct" :key="t.id" class="theme-opt" :class="{active:t.id===current}"><div class="theme-opt-main" @click="st(t.id)"><div class="theme-swatch-row"><span v-for="(c,i) in t.swatches" :key="i" class="theme-swatch" :style="{background:c}"/></div><span class="theme-opt-label">{{t.label}}</span><svg v-if="t.id===current" class="theme-check" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><polyline points="20 6 9 17 4 12"/></svg></div><button class="theme-del-btn" @click.stop="dlct(t.id)" title="Delete"><svg width="10" height="10" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg></button></div>
<button class="theme-add-btn" @click="opnpk"><svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><line x1="12" y1="5" x2="12" y2="19"/><line x1="5" y1="12" x2="19" y2="12"/></svg><span>Custom Color</span></button></div>
<div v-if="sp" class="theme-picker-panel"><div class="picker-header">Custom Color</div><div class="picker-preview-row"><div class="picker-preview" :style="{background:hv}"/><span class="picker-hex">{{hv}}</span></div>
<div class="picker-row"><span class="picker-label">R</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="r" @input="hsc" :style="{'--slider-color':`rgb(${r},0,0)`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="r" @input="hni"/></div>
<div class="picker-row"><span class="picker-label">G</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="g" @input="hsc" :style="{'--slider-color':`rgb(0,${g},0)`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="g" @input="hni"/></div>
<div class="picker-row"><span class="picker-label">B</span><input type="range" class="picker-slider" min="0" max="255" v-model.number="b" @input="hsc" :style="{'--slider-color':`rgb(0,0,${b})`}"/><input type="number" class="picker-num" min="0" max="255" v-model.number="b" @input="hni"/></div>
<div class="picker-actions"><button class="picker-btn picker-btn-cancel" @click="ccpk">Cancel</button><button class="picker-btn picker-btn-save" @click="svct">Save</button></div></div></div></template>
<style scoped>.theme-sep{height:1px;background:var(--border-subtle);margin:4px 6px}.theme-add-btn{display:flex;align-items:center;gap:6px;width:100%;padding:6px 8px;border:none;border-radius:6px;background:transparent;color:var(--muted);font-family:var(--font-mono);font-size:11px;cursor:pointer;transition:all .15s}.theme-add-btn:hover{background:var(--bg-hover);color:var(--accent)}.theme-opt-main{display:flex;align-items:center;gap:8px;flex:1;cursor:pointer}.theme-del-btn{display:flex;align-items:center;justify-content:center;width:20px;height:20px;border:none;border-radius:4px;background:transparent;color:var(--muted);cursor:pointer;flex-shrink:0;transition:all .15s}.theme-del-btn:hover{background:rgba(239,83,80,.15);color:var(--error)}.theme-picker-panel{position:absolute;top:100%;left:0;margin-top:6px;width:220px;background:var(--bg-surface);border:1px solid var(--border-subtle);border-radius:8px;box-shadow:0 8px 32px rgba(0,0,0,.5);z-index:201;padding:10px;animation:mc-in .15s var(--spring)}.picker-header{font-family:var(--font-mono);font-size:11px;color:var(--text);margin-bottom:8px;font-weight:600}.picker-preview-row{display:flex;align-items:center;gap:10px;margin-bottom:10px}.picker-preview{width:32px;height:32px;border-radius:6px;border:1px solid rgba(255,255,255,.15);flex-shrink:0}.picker-hex{font-family:var(--font-mono);font-size:13px;color:var(--text);font-weight:600}.picker-row{display:flex;align-items:center;gap:6px;margin-bottom:6px}.picker-label{font-family:var(--font-mono);font-size:11px;color:var(--muted);width:16px;flex-shrink:0}.picker-slider{-webkit-appearance:none;appearance:none;flex:1;height:4px;background:var(--border-subtle);border-radius:2px;outline:none;cursor:pointer}.picker-slider::-webkit-slider-thumb{-webkit-appearance:none;width:14px;height:14px;border-radius:50%;background:var(--slider-color,var(--accent));border:2px solid var(--bg-surface);cursor:pointer;transition:transform .15s}.picker-slider::-webkit-slider-thumb:hover{transform:scale(1.2)}.picker-num{width:42px;height:24px;background:var(--bg-input);border:1px solid var(--border-subtle);border-radius:4px;color:var(--text);font-family:var(--font-mono);font-size:11px;text-align:center;outline:none;flex-shrink:0}.picker-num:focus{border-color:var(--accent)}.picker-num::-webkit-inner-spin-button,.picker-num::-webkit-outer-spin-button{-webkit-appearance:none;margin:0}.picker-actions{display:flex;gap:6px;margin-top:10px}.picker-btn{flex:1;padding:6px 0;border:none;border-radius:6px;font-family:var(--font-mono);font-size:11px;cursor:pointer;transition:all .15s}.picker-btn-cancel{background:var(--bg-hover);color:var(--text-body)}.picker-btn-cancel:hover{background:var(--border-subtle)}.picker-btn-save{background:var(--accent);color:var(--bg-deep);font-weight:600}.picker-btn-save:hover{filter:brightness(1.1)}</style>
